package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;

/**
 * Unit tests for UniformRealDistribution#isSupportUpperBoundInclusive
 */
public class UniformRealDistribution_isSupportUpperBoundInclusive_TriageGen2Test {

    @Test
    public void testIsSupportUpperBoundInclusive_DefaultConstructor() {
        // Default constructor uses default values (usually 0.0, 1.0)
        UniformRealDistribution distribution = new UniformRealDistribution();
        assertFalse("The upper bound should not be inclusive for a default UniformRealDistribution", 
            distribution.isSupportUpperBoundInclusive());
    }

    @Test
    public void testIsSupportUpperBoundInclusive_WithParameters() {
        // Testing with specific lower and upper bounds
        UniformRealDistribution distribution = new UniformRealDistribution(0.0, 10.0);
        assertFalse("The upper bound should not be inclusive for a UniformRealDistribution with parameters", 
            distribution.isSupportUpperBoundInclusive());
    }

    @Test
    public void testIsSupportUpperBoundInclusive_WithInverseCumAccuracy() {
        // Testing with lower, upper, and inverseCumAccuracy
        UniformRealDistribution distribution = new UniformRealDistribution(0.0, 1.0, 1e-12);
        assertFalse("The upper bound should not be inclusive for a UniformRealDistribution with inverseCumAccuracy", 
            distribution.isSupportUpperBoundInclusive());
    }

    @Test
    public void testIsSupportUpperBoundInclusive_WithRandomGenerator() {
        // Testing with a RandomGenerator (using a dummy/default one if possible, 
        // but since we only care about the return value of isSupportUpperBoundInclusive, 
        // we just need to instantiate it)
        org.apache.commons.math3.random.JDKRandomGenerator rng = new org.apache.commons.math3.random.JDKRandomGenerator();
        UniformRealDistribution distribution = new UniformRealDistribution(rng, 0.0, 1.0, 1e-12);
        assertFalse("The upper bound should not be inclusive for a UniformRealDistribution with RandomGenerator", 
            distribution.isSupportUpperBoundInclusive());
    }
}
